Your expense tracker for Nov 2026 is below. Add an item, pick a category, and it totals by category with a budget bar. I can't promise it keeps entries after you close this chat, so note down anything important.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><style>
body{font-family:Segoe UI,sans-serif;margin:0;padding:12px;background:#f7f7f5;color:#222}
h2{margin:0 0 8px;font-size:18px}
.row{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px}
input,select,button{padding:7px;border:1px solid #ccc;border-radius:6px;font-size:14px}
button{background:#2f7d5b;color:#fff;border:0;cursor:pointer}
button.x{background:#c0392b;padding:3px 8px}
.card{background:#fff;border-radius:8px;padding:10px;margin-bottom:10px}
.bar{background:#e4e4e0;border-radius:4px;height:8px;margin:2px 0 8px}
.bar div{background:#2f7d5b;height:8px;border-radius:4px}
.over{color:#c0392b;font-weight:600}
.item{display:flex;justify-content:space-between;align-items:center;padding:4px 0;border-bottom:1px solid #eee;font-size:14px}
.big{font-size:22px;font-weight:600}
</style></head><body>
<h2>Expenses, Nov 2026</h2>
<div class="card">
<div class="row">
<input id="d" placeholder="What for?" style="flex:2;min-width:100px">
<select id="c"><option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Fun</option><option>Other</option></select>
<input id="a" type="number" min="0" placeholder="Amount (₹)" style="flex:1;min-width:90px">
<button onclick="add()">Add</button>
</div>
<div class="row">Monthly budget (₹): <input id="b" type="number" min="0" value="50000" oninput="draw()" style="width:110px"></div>
</div>
<div class="card">
<div class="big" id="tot">₹0</div>
<div id="left"></div>
<div class="bar"><div id="pb" style="width:0%"></div></div>
<div id="cats"></div>
</div>
<div class="card"><b>Entries</b><div id="list"></div></div>
<script>
var items=[];
try{items=JSON.parse(localStorage.getItem('exp')||'[]')}catch(e){}
function fmt(n){return '₹'+Number(n).toLocaleString('en-IN')}
function save(){try{localStorage.setItem('exp',JSON.stringify(items))}catch(e){}}
function add(){
var a=parseFloat(document.getElementById('a').value);
if(!(a>0))return;
items.push({d:document.getElementById('d').value||'Untitled',c:document.getElementById('c').value,a:a});
document.getElementById('d').value='';document.getElementById('a').value='';
save();draw();
}
function del(i){items.splice(i,1);save();draw()}
function draw(){
var t=0,by={};
items.forEach(function(x){t+=x.a;by[x.c]=(by[x.c]||0)+x.a});
var b=parseFloat(document.getElementById('b').value)||0;
document.getElementById('tot').textContent=fmt(t)+' spent';
var l=document.getElementById('left');
l.innerHTML=b?(t>b?'<span class="over">Over budget by '+fmt(t-b)+'</span>':fmt(b-t)+' left of '+fmt(b)):'';
var p=b?Math.min(100,t/b*100):0;
document.getElementById('pb').style.width=p+'%';
var h='';
Object.keys(by).sort(function(x,y){return by[y]-by[x]}).forEach(function(k){
h+='<div>'+k+': '+fmt(by[k])+'</div><div class="bar"><div style="width:'+(by[k]/t*100)+'%"></div></div>';
});
document.getElementById('cats').innerHTML=h;
var s='';
items.forEach(function(x,i){
s+='<div class="item"><span>'+x.d.replace(/</g,'&lt;')+' <small>('+x.c+')</small></span><span>'+fmt(x.a)+' <button class="x" onclick="del('+i+')">x</button></span></div>';
});
document.getElementById('list').innerHTML=s||'<small>Nothing yet.</small>';
}
draw();
</script></body></html>
```

